import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Restaurant","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/08-restaurant.md","filePath":"generated/modules/08-restaurant.md","lastUpdated":null}'),n={name:"modules/08-restaurant.md"};function r(o,a,i,l,p,c){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="restaurant" tabindex="-1">Restaurant <a class="header-anchor" href="#restaurant" aria-label="Permalink to &quot;Restaurant&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 2 · <a href="/VendoraSystem-docs/specs/08-restaurant">spécification complète</a></span></p><p>Plan de salle, additions ouvertes avec envois successifs, modificateurs, routage par poste (bons imprimés et KDS), téléphone de salle, opérations sur additions et encaissement (tout, parts égales, par articles, à la table). Toute la phase 2 est livrée sur les deux apps, le serveur et le back-office (lots 2.1 → 2.15, reliquats 2.26) et prouvée sur la vraie stack ; restent le son / la notification « prêt », l&#39;affichage KDS des annulations et des alertes, l&#39;intégration kiosque (phase 4) et le food-cost (phase 3).</p><div class="kpis"><div><b>30</b><span>faites</span></div><div><b>4</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="plan-de-salle" tabindex="-1">Plan de salle <a class="header-anchor" href="#plan-de-salle" aria-label="Permalink to &quot;Plan de salle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Éditeur de plan de salle</strong><br><span class="muted">La gérante crée des zones et pose, modifie, déplace ou retire des tables (nom, capacité, forme) au back-office, publication versionnée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-01, RG-REST-02</td><td>2.1, 2.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-plan-de-salle">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs-suite">📷</a></td></tr><tr><td><strong>Plan de salle sur les appareils</strong><br><span class="muted">Caisse et téléphone de salle affichent les tables par zone avec leur statut dérivé (libre, occupée, addition demandée) et leur total, relus à chaque synchro.<br><i>CA 1 « &lt; 5 s après publication » : mesuré ~7 s par le pull périodique de 20 s (case non cochée au lot 2.1).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-02, RG-REST-03</td><td>2.1, 2.2, 2.5, UX3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-plan-de-salle">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-addition-table">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-android">📷</a></td></tr><tr><td><strong>Accès aux tables sur la caisse</strong><br><span class="muted">La caisse arrive sur le plan de salle ou sur la vente directe selon le profil du magasin (restaurant → tables), ou selon le réglage de l&#39;appareil au back-office ; une bascule « Tables | Vente directe » toujours visible en tête de la vente et du plan remplace l&#39;entrée du menu ⋮.<br><i>Appliqué à chaque connexion (et au redémarrage avec session restaurée), la bascule reste libre ensuite. Sans table au plan : toujours la vente. Appareil appairé avant ce lot : vente, comme avant, jusqu&#39;à la prochaine publication de sa configuration.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-02, RG-THEME-06</td><td>Accès aux tables</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-acces-tables">📷</a></td></tr><tr><td><strong>Module « tables » réservé au profil restaurant</strong><br><span class="muted">Le plan de salle n&#39;est proposé qu&#39;aux magasins de profil RESTAURANT ayant le module tables actif.<br><i>Reste du lot 2.1 : la notion de module <code>tables</code> par profil n&#39;existe pas encore (la bascule « Tables » apparaît dès que le magasin a des tables). Depuis le lot « accès aux tables », le profil RESTAURANT fait arriver la caisse sur le plan de salle.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-REST-01</td><td>2.1</td><td></td></tr></tbody></table><h2 id="addition-ouverte" tabindex="-1">Addition ouverte <a class="header-anchor" href="#addition-ouverte" aria-label="Permalink to &quot;Addition ouverte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ouverture d&#39;une addition avec couverts</strong><br><span class="muted">Un tap sur une table libre demande le nombre de couverts et ouvre l&#39;addition (une seule addition ouverte par table).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-03, RG-REST-04</td><td>2.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-addition-table">📷</a></td></tr><tr><td><strong>Envois successifs en cuisine</strong><br><span class="muted">Le serveur compose un brouillon local puis l&#39;envoie en cuisine ; chaque envoi est numéroté et ses lignes envoyées ne sont plus modifiables.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-05, RG-REST-06, RG-REST-07</td><td>2.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-addition-table">📷</a></td></tr></tbody></table><h2 id="modificateurs" tabindex="-1">Modificateurs <a class="header-anchor" href="#modificateurs" aria-label="Permalink to &quot;Modificateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Groupes de modificateurs</strong><br><span class="muted">Choix unique ou multiple, suppléments payants, choix obligatoire bloquant, prix de la ligne = (produit + suppléments) × quantité, au restaurant comme au comptoir.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-08, RG-REST-09</td><td>2.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs-suite">📷</a></td></tr><tr><td><strong>Note cuisine libre</strong><br><span class="muted">Le serveur ajoute une note libre à une ligne (au choix des modificateurs ou sur la ligne), imprimée « ! » sur le bon.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-08</td><td>2.3, 2.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs">📷</a></td></tr></tbody></table><h2 id="routage-cuisine" tabindex="-1">Routage cuisine <a class="header-anchor" href="#routage-cuisine" aria-label="Permalink to &quot;Routage cuisine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Postes de préparation et routage</strong><br><span class="muted">La gérante définit ses postes (imprimante, largeur, délai cible) et y route des catégories ou des produits, un poste au plus par catégorie / produit.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-10</td><td>2.4, 2.5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-bons-cuisine">📷</a></td></tr><tr><td><strong>Un bon imprimé par poste</strong><br><span class="muted">À chaque envoi, un bon par poste (table et poste en double taille, serveur, heure, modificateurs, sans prix) est enfilé dans la file durable, avec réimpression marquée.<br><i>Prouvé avec deux fausses imprimantes TCP ; impression sur imprimantes cuisine réelles : VALIDATION-MATERIEL §3.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-11, RG-HW-04, RG-HW-07</td><td>2.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-bons-cuisine">📷</a></td></tr><tr><td><strong>Imprimeur unique désigné au back-office</strong><br><span class="muted">Le back-office désigne l&#39;appareil qui imprime les bons des autres appareils ; le serveur exige un appareil actif du magasin.<br><i>Prouvé entre émulateur et simulateur ; « un seul appareil imprime les bons des téléphones » reste à rejouer sur appareils physiques (TODO-PHASE1 §1).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-11</td><td>2.4, 2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Alerte imprimante de poste injoignable</strong><br><span class="muted">Quand la file est suspendue sur l&#39;imprimante d&#39;un poste, l&#39;appareil émet <code>KitchenTicketPrintFailed</code>, affiche l&#39;alerte et le back-office la remonte dans les alertes d&#39;intégrité.<br><i>L&#39;alerte n&#39;est pas encore affichée sur le KDS du poste (reste du lot 2.26).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-12, RG-HW-07</td><td>2.17, 2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Bon d&#39;annulation au poste</strong><br><span class="muted">L&#39;annulation d&#39;une ligne envoyée enfile un bon « ANNULATION » au poste de la ligne, avec la mention « déjà prêt / servi » le cas échéant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-07</td><td>2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr></tbody></table><h2 id="kds" tabindex="-1">KDS <a class="header-anchor" href="#kds" aria-label="Permalink to &quot;KDS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Écran cuisine : file du poste et cycle d&#39;états</strong><br><span class="muted">Le KDS affiche les bons de son poste triés par envoi ; le chef fait passer Reçu → En préparation → Prêt, avec rappel Prêt → En préparation (compare-and-set, jamais de recul au rejeu).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-13, RG-REST-14, RG-REST-17</td><td>2.5, UX3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-ecran-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-android">📷</a></td></tr><tr><td><strong>Temps écoulé et alerte de délai</strong><br><span class="muted">Chaque bon affiche son temps écoulé et passe en alerte rouge au-delà du délai cible du poste.<br><i>Lot R3 : son au dépassement (option par poste), un bip par bon passé en alerte. Lot T : « De côté » range un envoi jamais traité en bas de l&#39;écran, sans alerte ni son, « Reprendre » le remet dans la file (local à l&#39;écran).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-14</td><td>2.5, R3, T, UX3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-ecran-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-r3-restaurant">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-t-tablette">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-android">📷</a></td></tr><tr><td><strong>Annulation barrée sur le KDS</strong><br><span class="muted">Une ligne annulée apparaît barrée en rouge « ANNULÉ » sur le KDS au lieu de disparaître.<br><i>Lot R3 : la ligne annulée (ou l&#39;addition entière) reste dans son bon, barrée en rouge « ANNULÉ » avec le motif, jusqu&#39;au prochain tap du chef ; un bon entièrement annulé s&#39;affiche « ANNULÉ » et « Vu » le retire ; une annulation non vue disparaît d&#39;elle-même après 2 h ; rien n&#39;est montré pour une ligne déjà servie.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-07</td><td>2.8, R3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r3-restaurant">📷</a></td></tr><tr><td><strong>Affectation d&#39;un KDS à un poste au back-office</strong><br><span class="muted">Le back-office rattache un appareil KDS à un poste (<code>kdsDeviceId</code>) et montre quels écrans affichent quel poste.<br><i>Lot R3 : écran affecté au poste depuis le back-office. Lot T : « Chef : … » sur l&#39;écran cuisine (équipe du magasin, sans PIN — KDS sans connexion, spec 01 §4) ; chaque transition porte son identifiant (<code>changedByUserId</code>).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-11</td><td>2.5, R3, T</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r3-restaurant">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-t-tablette">📷</a></td></tr></tbody></table><h2 id="salle" tabindex="-1">Salle <a class="header-anchor" href="#salle" aria-label="Permalink to &quot;Salle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Avis « prêt » au serveur</strong><br><span class="muted">Quand un envoi est prêt, la caisse et le téléphone affichent l&#39;avis « Table X — Envoi N prêt (Poste) », les lignes « Prêt » et un badge « Prêt ×n » sur le plan.<br><i>Lot R3 : notification système avec son, même caisse verrouillée. Lot T : le téléphone de salle ne sonne que pour les tables de son serveur (dernier utilisateur connecté), la caisse reçoit tout en repli. Reste hors code : push distant (APNs / FCM) quand l&#39;app est fermée, avec les identifiants Apple et Google.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-15</td><td>2.5, R3, T</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-ecran-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-r3-restaurant">📷</a></td></tr><tr><td><strong>Téléphone de salle (WAITER_TERMINAL)</strong><br><span class="muted">Le serveur ouvre directement le plan de salle et ses additions sur son téléphone : prise de commande, envoi, addition, pré-addition, opérations.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-04, RG-REST-05</td><td>2.5, 2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr></tbody></table><h2 id="temps-reel-local" tabindex="-1">Temps réel local <a class="header-anchor" href="#temps-reel-local" aria-label="Permalink to &quot;Temps réel local&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Service complet sans internet</strong><br><span class="muted">Envoi → KDS → changement d&#39;état → « Servi » transitent par le hub local du magasin, serveur cloud arrêté, avec rattrapage d&#39;un appareil arrivé en retard.<br><i>Prouvé entre simulateur iPhone et émulateur Android (≤ 275 ms) ; latence &lt; 2 s et chute du hub à rejouer sur 3 appareils physiques (VALIDATION-MATERIEL §7).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-16, RG-REST-17</td><td>2.6, 2.26, 2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a></td></tr></tbody></table><h2 id="encaissement" tabindex="-1">Encaissement <a class="header-anchor" href="#encaissement" aria-label="Permalink to &quot;Encaissement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Demande d&#39;addition et pré-addition PRO FORMA</strong><br><span class="muted">Le serveur demande l&#39;addition (table violette partout, rouverte par un nouvel envoi) et imprime une pré-addition non fiscale marquée PRO FORMA.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-23</td><td>2.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a></td></tr><tr><td><strong>Encaissement d&#39;une addition à la caisse</strong><br><span class="muted">La caisse encaisse tout ou le reste d&#39;une addition avec sa feuille de paiement habituelle ; chaque part est une vente scellée liée à l&#39;addition, la table se libère au solde nul. Quand le magasin interdit le stock négatif, l&#39;encaissement d&#39;une addition au-delà du stock demande le PIN d&#39;un manager et un motif (lot 3.9).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-21, RG-REST-22</td><td>2.7, 3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-preuves-push">📷</a></td></tr><tr><td><strong>Partage en parts égales</strong><br><span class="muted">L&#39;addition est réglée en N parts dont la somme est exacte au centime (100,00 en 3 → 33,34 / 33,33 / 33,33), éventuellement sur plusieurs caisses.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-19</td><td>0.x, 2.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a></td></tr><tr><td><strong>Partage par articles</strong><br><span class="muted">Chaque part regroupe des lignes choisies ; une ligne de quantité &gt; 1 peut être réglée en quantités entières (2 puis 1).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-19</td><td>2.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a></td></tr><tr><td><strong>Encaissement à la table par le téléphone</strong><br><span class="muted">Le téléphone de salle encaisse selon la politique choisie par l&#39;owner : session de la caisse principale désignée ou session propre sans tiroir.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-21, RG-CASH-23, RG-CASH-24, RG-CASH-25, RG-CASH-26</td><td>2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr></tbody></table><h2 id="operations-sur-additions" tabindex="-1">Opérations sur additions <a class="header-anchor" href="#operations-sur-additions" aria-label="Permalink to &quot;Opérations sur additions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Annulation d&#39;une ligne envoyée</strong><br><span class="muted">Une ligne envoyée est annulée sous PIN manager avec motif, barrée sur l&#39;addition et journalisée (opérateur et approbatrice).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-07</td><td>2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr><tr><td><strong>Ligne offerte</strong><br><span class="muted">Une ligne est offerte sous PIN manager avec motif : facturée 0, prix d&#39;origine conservé pour le reporting, stock sorti quand même.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-20</td><td>2.8, 2.11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-service-back-office">📷</a></td></tr><tr><td><strong>Transfert vers une table libre</strong><br><span class="muted">Une addition ouverte est déplacée vers une table libre ; vers une table occupée, l&#39;app propose la fusion.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-18</td><td>2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr><tr><td><strong>Fusion de deux additions</strong><br><span class="muted">Deux additions ouvertes sont fusionnées : envois renumérotés à la suite, états conservés, source MERGED, table libérée.<br><i>Fusion refusée dès qu&#39;une des deux additions a un encaissement ; les brouillons de la source ne suivent que sur l&#39;appareil qui fusionne.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-18</td><td>2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr><tr><td><strong>Convergence d&#39;une table ouverte sur deux appareils</strong><br><span class="muted">Deux appareils hors ligne ouvrant la même table : la plus ancienne addition gagne, la perdante est fusionnée et l&#39;écran suit la gagnante, numérotation identique partout.<br><i>Une perdante partiellement encaissée coexiste et se règle à la main ; deux caisses encaissant la même addition en partition réseau ne sont pas verrouillées (reste du lot 2.7).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-25</td><td>2.12, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-convergence-table">📷</a></td></tr><tr><td><strong>Annulation d&#39;une addition entière</strong><br><span class="muted">Un manager annule une addition complète (CANCELLED) sous PIN et motif.<br><i>Lot R3 : « ⋯ › Annuler l&#39;addition » (Android, iOS) sous PIN manager + motif (<code>ORDER_CANCEL</code>), refusée dès qu&#39;une part est encaissée ; événement <code>OrderCancelled</code> : lignes VOIDED, brouillons jetés, table libre, bons d&#39;ANNULATION en cuisine ; serveur : addition « Annulée » avec motif dans l&#39;historique du back-office, audit <code>ORDER / CANCELLED</code> avec approbateur, comptée dans la fréquence d&#39;annulations (anti-fraude).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-REST-04</td><td>2.8, R3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r3-restaurant">📷</a></td></tr></tbody></table><h2 id="back-office" tabindex="-1">Back-office <a class="header-anchor" href="#back-office" aria-label="Permalink to &quot;Back-office&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Page « Service » et projection des additions</strong><br><span class="muted">Le back-office voit le service en cours et les additions closes, leur détail (offerts, annulations, parts) et les indicateurs (couverts, ticket moyen, gaspillage après « prêt »).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>2.11, 2.13</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-service-back-office">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a></td></tr><tr><td><strong>Délais et retards par poste</strong><br><span class="muted">Le tableau « par poste » donne lignes routées, prêtes, délai moyen envoi → prêt, cible et retards.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-10, RG-REST-14</td><td>2.13</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a></td></tr></tbody></table><h2 id="kiosque" tabindex="-1">Kiosque <a class="header-anchor" href="#kiosque" aria-label="Permalink to &quot;Kiosque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Commandes kiosque sans table</strong><br><span class="muted">Une commande du kiosque crée une addition à emporter / comptoir avec un numéro de retrait court affiché sur le KDS et le bon.<br><i>Phase 4 (spec 09) ; les numéros séquentiels alloués par le hub restent ouverts (reste du lot 2.6).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-REST-24</td><td></td><td></td></tr></tbody></table><h2 id="food-cost" tabindex="-1">Food-cost <a class="header-anchor" href="#food-cost" aria-label="Permalink to &quot;Food-cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Fiches techniques des plats</strong><br><span class="muted">Un plat référence une nomenclature versionnée d&#39;ingrédients ; son coût de revient théorique est calculé aux CMP.<br><i>Livré au lot 3.14 (02/11/2026) : fiche sur la fiche produit, versions, coût de revient, food-cost et marge à la saisie, module Écrans cuisine, diffusion aux caisses.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-25</td><td>3.14</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-314-food-cost">📷</a></td></tr><tr><td><strong>Marge par plat et alerte de dérive</strong><br><span class="muted">Marge figée à la vente et alerte quand le coût réel s&#39;écarte du coût théorique au-delà d&#39;un seuil.<br><i>Livré au lot 3.14 : coût figé à la vente, page Food-cost théorique / réel, dérive au-delà du seuil du magasin (10 % par défaut). Reste : alerte poussée (email / notification).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-26, RG-REST-27</td><td>3.14</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-314-food-cost">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Son et notification push « prêt » sur le téléphone du serveur.</li><li>Lignes annulées affichées barrées sur le KDS et alerte d&#39;imprimante de poste affichée sur le KDS.</li><li>Affectation des KDS aux postes au back-office ; utilisateur tracé sur les transitions faites en cuisine.</li><li>Annulation d&#39;une addition entière par un manager.</li><li>Module « tables » activable par profil de magasin.</li><li>Rendu ESC/POS : le séparateur « · » devient « ? » (code page à faire) ; bons cuisine non distingués dans l&#39;écran de la file d&#39;impression.</li><li>Ordre des groupes de modificateurs par produit ; agrégation des options dans les rapports par produit.</li><li>Page Service : rafraîchissement automatique et export.</li><li>Captures manquantes : KDS iOS, téléphone de salle Android en prise de commande, offert / annulation sur iOS.</li><li>Validation du service sans internet sur 3 appareils physiques (VALIDATION-MATERIEL §7).</li><li>Intégration kiosque (phase 4) et food-cost (phase 3).</li></ul>',30)])])}const h=t(n,[["render",r]]);export{b as __pageData,h as default};
